import os,sys,random,datetime,subprocess
from pathlib import Path
os.environ['CUDA_VISIBLE_DEVICES']='';sys.path.insert(0,'scripts')
from round034_core import R,D,PY,read,rows,sha,write
def main():
 assert not (R/'experiment-plan.json').exists();assert read(R/'closure-independent-audit.json')['passed'];cpu=read(R/'supervision-CPU-audit.json');assert cpu['passed'] and cpu['total_rows']==827 and cpu['CPU_expert_gold_passed']==32
 assert read(R/'preflight-job.json')['exit_code']==read(R/'checkpointed-preflight-job.json')['exit_code']==0;assert read(R/'preflight-result.json')['optimizer_steps']==read(R/'checkpointed-preflight-result.json')['optimizer_steps']==0;assert read(R/'checkpointed-preflight-result.json')['passed'] and read(R/'checkpointed-preflight-result.json')['longest_full_tokens']==2955
 old=read(R.parent/'round-033-2026-10-10/pilot-plan.json');files=dict(old['sha256']);order=list(range(827));random.Random(49).shuffle(order);models={'source':old['source_model'],'mixed49':'outputs/repro_round034/mixed49/final','lr0_49':'outputs/repro_round034/lr0_49/final'}
 worlds={'old':'data/repro_20261002/snapshot_curated_v1.json','trainA':'data/repro_round024/trainA-snapshot.json','trainB':'data/repro_round024/trainB-snapshot.json'};groups=read(R.parent/'round-031-2026-10-09/experiment-plan.json')['groups'];retention={}
 for name in ['olddev','newdev']:
  g=groups[name];f,key=g['split'].rsplit(':',1);ids=read(f)['split'][key];ts=[t for t in read(g['tasks']) if t['id'] in ids];assert len(ts)==(8 if name=='olddev' else 16);write(R/(name+'-tasks.json'),ts);retention[name]=str(R/(name+'-tasks.json'))
 jobs={};train_tasks=str(R.parent/'round-033-2026-10-10/TRAIN-unique-tasks.json');fresh=str(R/'confirmation-tasks.json')
 for m in models:jobs[f'{m}-plan-TRAIN-s49']={'model':m,'route':'plan','group':'TRAIN','seed':49,'repeat':1,'tasks':train_tasks,'expected_full_trials':96}
 for seed in [49,50]:
  for m in models:
   for g,w in [('olddev','old'),('newdev','trainA')]:jobs[f'{m}-native-{g}-s{seed}']={'model':m,'route':'native','group':g,'world':w,'seed':seed,'repeat':3,'tasks':retention[g],'expected_full_trials':24 if g=='olddev' else 48}
  for w in ['trainA','trainB']:jobs[f'source-native-confirm{w[-1]}-s{seed}']={'model':'source','route':'native','group':'confirmation','world':w,'seed':seed,'repeat':3,'tasks':fresh,'expected_full_trials':48}
  for m in models:jobs[f'{m}-plan-confirm-s{seed}']={'model':m,'route':'plan','group':'confirmation','seed':seed,'repeat':3,'tasks':fresh,'expected_full_trials':96}
 assert len(jobs)==25 and sum(x['expected_full_trials'] for x in jobs.values())==1488
 sources=['round034_core.py','audit_round034_closure.py','prepare_round034_supervision.py','train_round034_plan.py','run_round034_eval.py','finalize_round034_study.py','run_round034_study.py','register_round034_study.py']
 for f in [Path('scripts')/s for s in sources]+[D/'mixed-supervision.jsonl',D/'plan-supervision.jsonl']+[R/n for n in ['closure-independent-audit.json','supervision-CPU-audit.json','confirmation-tasks.json','confirmation-gold.jsonl','confirmation-preparation-plan.json','preflight-plan.json','preflight-result.json','checkpointed-preflight-plan.json','checkpointed-preflight-result.json','preflight-training-source.py','pre-learning-output-adjustment.json','olddev-tasks.json','newdev-tasks.json']]:files[str(f)]=sha(f)
 for f in worlds.values():files[f]=sha(f)
 for f,h in files.items():assert sha(f)==h,f
 p={'registered_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'question':'Does new complete-plan supervision plus unchanged native TRAIN replay learn the frozen plan representation, outperform retained native ReAct on prospectively selected programs, and retain native old/new Dev behavior?','new_hypothesis_not_reopening_closed_zero_shot_pilot':True,'source_model':old['source_model'],'model_paths':models,'learning_permitted':True,'learning_arms':['mixed49','lr0_49'],'training_seed':49,'training_seeds_count':1,'training_data':str(D/'mixed-supervision.jsonl'),'training_order':order,'dataset':{'plan_unique':48,'plan_repeats':8,'plan_rows':384,'original_native_rows':443,'native_experts':398,'native_certified_errors':45,'total_rows':827,'no_confirmation_or_Dev_labels':True},'learning_recipe':{'objective':'sample-mean completion-only CE, prompt mask -100, no KL/RL, disabled dropout','source_QLoRA_continuation':True,'epochs':1,'optimizer_steps_each':207,'expected_actual_positive_lr_steps_mixed49':206,'control_positive_lr_steps':0,'batch':1,'gradient_accumulation':4,'last_group':3,'mixed_learning_rate':5e-6,'control_learning_rate':0.,'scheduler':'cosine','warmup_ratio':.03,'optimizer':'paged_adamw_8bit','max_full_tokens':4096,'truncation':0,'gradient_checkpointing':'nonreentrant','bf16':True,'no_intermediate_checkpoint_selection':True},'worlds':worlds,'eval_jobs':jobs,'inference_jobs':25,'full_trial_scores':1488,'actual_plan_model_calls':432,'logical_plan_runs':864,'native_full_trial_runs':624,'generation_seeds':[49,50],'runtime':'Frozen R033 PlanAgent and native ArmBlindAgent, temp.1/cap1000/BF16, no inference format/prompt change. Plan predictions uniformly reused in two old worlds, full cost charged each logical run. All finals frozen before any eval. Complete proposal scoring PRIMARY including skipped/invalid proposals; executed metric SECONDARY.','ALL_rules':['TRAIN mixed plan strict>=44/48, parse>=46/48, capclipped0 both worlds','Each generation seed and each new world: mixed plan PRIMARY strict>=max(source native,source plan,lr0 plan)+3/48','Each seed old/new Dev native strict>=max(source,lr0) AND FF<=min(source,lr0)','Each seed/new world plan FF<=min(source native,source plan,lr0 plan)','Each seed/new world plan logical prompt+completion tokens<=50% source native','Each seed/new world plan parse>=46/48 and capclipped0'],'failure':'Close this fixed learning recipe; no prompt/lr/repeat/seed/case/checkpoint sweep. Source remains default, no automatic deployment or further learning.','confirmation':{'families':['FSAC','FSCA'],'requests':16,'worlds':2,'sequences_not_used_prior':True,'shared_TRAIN_tools_params_subsequences_and_papers':True,'CPU32_gold_not_model_gain':True,'not_broad_or_paper_blind_or_significance_claim':True},'control':'Same order/dropout/optimizer calls, lr0 trainable tensors must equal source; fresh source native baseline regenerated. One learning seed and two generation seeds, not two independently trained candidates. Mixed supervision/replay treated as one route, no component-causal claim.','allowed_physical_gpus':[4,7],'training_minimum_free_mib':23000,'training_UUID_compute_processes':0,'inference_minimum_free_mib':8192,'no_preemption':True,'controller_timeout_seconds':64800,'training_job_timeout_seconds':5400,'inference_job_timeout_seconds':3600,'sha256':files};write(R/'experiment-plan.json',p);log=(R/'controller.log').open('a');child=subprocess.Popen(['nohup','timeout','--kill-after=30','64800',PY,'-u','scripts/run_round034_study.py'],stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,start_new_session=True);write(R/'launch.json',{'launched_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pid':child.pid,'plan_sha256':sha(R/'experiment-plan.json'),'finite_timeout_seconds':64800,'training_candidates':1,'lr0_controls':1,'no_periodic_automation':True,'allowed_physical_gpus':[4,7]});print(read(R/'launch.json'))
if __name__=='__main__':main()
